counting_levels.code:
def solve(citations):
    n = len(citations)
    h1 = [0] * (n + 1)
    for c in citations:
        if c <= n:
            h1[c] += 1
        else:
            h1[n] += 1
    total = 0
    for i in range(n, -1, -1):
        total += h1[i]
        if total >= i:
            return i
    return 0

