binary_search_h.code:
def solve(citations):
    n = len(citations)
    left, right = (0, n)
    while left < right:
        mid = (left + right + 1) // 2
        count = sum((1 for c in citations if c >= mid))
        if count >= mid:
            left = mid
        else:
            right = mid - 1
    return left

